source:
source note sys.dataset(fields: [title, subtitle, status, summary, as_of, metric1_label, metric1_value, metric2_label, metric2_value, pick1_title, pick1_body, pick2_title, pick2_body])

copy app { class: vocabulary, en: "Mail" }
copy sim { class: vocabulary, en: "Simulation — no real parcel" }
copy b_show_code { class: vocabulary, en: "Show code" }
copy b_details { class: vocabulary, en: "Details" }
copy b_back { class: vocabulary, en: "Back" }
copy c_code_head { class: vocabulary, en: "Pickup code" }
copy c_code_req { class: vocabulary, en: "Bring this code and photo ID to the desk." }
copy c_where { class: vocabulary, en: "Where" }
copy c_deadline { class: vocabulary, en: "Deadline" }
copy c_tracking { class: vocabulary, en: "Tracking ref" }
copy c_nolink { class: vocabulary, en: "No tracking website is provided for this parcel." }
copy next_step { class: model-copy, en: "Next step: go to the pickup desk with your code and photo ID." }
copy gist { class: model-copy, en: "With no redelivery arranged, the Oct 5 deadline is the hard constraint: collect before 9:00 PM PDT, or the parcel stays at the desk." }

state mode { shape: enum[brief, code, details], initial: .brief }
event show_code { mode: set(.code) }
event details { mode: set(.details) }
event back { mode: set(.brief) }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: note.as_of)
    }
    TextCaption(text: copy.sim, width: .fill)

    when mode == .brief {
      Col(gap: 8) {
        TextTitle(text: note.title, width: .fill)
        TextCaption(text: note.subtitle, width: .fill)
        TextBody(text: note.summary, width: .fill)
        Row(gap: 8) {
          TextCaption(text: note.metric1_label)
          TextCaption(text: note.metric1_value, width: .fill)
        }
        Row(gap: 8) {
          TextCaption(text: note.pick1_title)
          TextBody(text: note.pick1_body, width: .fill)
        }
        TextBody(text: copy.next_step, width: .fill)
        Col(gap: 8) {
          Chip(text: copy.b_show_code, on_tap: show_code, tone: .primary, width: .fill)
          Chip(text: copy.b_details, on_tap: details, width: .fill)
        }
      }
    }

    when mode == .code {
      Col(gap: 8) {
        TextTitle(text: note.title, width: .fill)
        TextCaption(text: note.subtitle, width: .fill)
        TextCaption(text: copy.c_code_head)
        TextTitle(text: note.pick2_title)
        TextBody(text: note.pick2_body, width: .fill)
        TextBody(text: copy.c_code_req, width: .fill)
        Row(gap: 8) {
          TextCaption(text: note.metric1_label)
          TextCaption(text: note.metric1_value, width: .fill)
        }
        Row(gap: 8) {
          TextCaption(text: note.pick1_title)
          TextBody(text: note.pick1_body, width: .fill)
        }
        Chip(text: copy.b_back, on_tap: back, tone: .primary, width: .fill)
      }
    }

    when mode == .details {
      Col(gap: 8) {
        TextTitle(text: note.title, width: .fill)
        TextCaption(text: note.subtitle, width: .fill)
        TextBody(text: note.summary, width: .fill)
        Row(gap: 8) {
          TextCaption(text: copy.c_where)
          TextBody(text: note.pick1_body, width: .fill)
        }
        Row(gap: 8) {
          TextCaption(text: note.metric2_label)
          TextCaption(text: note.metric2_value, width: .fill)
        }
        Row(gap: 8) {
          TextCaption(text: copy.c_deadline)
          TextCaption(text: note.metric1_value, width: .fill)
        }
        Row(gap: 8) {
          TextCaption(text: copy.c_tracking)
          TextCaption(text: note.status, width: .fill)
        }
        TextCaption(text: copy.c_nolink, width: .fill)
        TextBody(text: copy.gist, width: .fill)
        Chip(text: copy.b_back, on_tap: back, tone: .primary, width: .fill)
      }
    }
  }
}
